CREATE OR REPLACE FUNCTION public.get_emergency_station_today_completed_pre_start_ready()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_catalog'
AS $function$
DECLARE
  v_rows jsonb;
  v_day_start timestamptz;
  v_day_end timestamptz;
BEGIN
  v_day_start := (
    (now() AT TIME ZONE 'Asia/Ho_Chi_Minh')::date::timestamp
    AT TIME ZONE 'Asia/Ho_Chi_Minh'
  );
  v_day_end := v_day_start + interval '1 day';
  v_rows := public.get_emergency_station_today_completed_pre_business_day();

  RETURN COALESCE((
    SELECT jsonb_agg(entry.raw ORDER BY entry.ord)
    FROM jsonb_array_elements(COALESCE(v_rows, '[]'::jsonb))
      WITH ORDINALITY entry(raw, ord)
    WHERE NULLIF(entry.raw->>'created_at', '')::timestamptz >= v_day_start
      AND NULLIF(entry.raw->>'created_at', '')::timestamptz < v_day_end
  ), '[]'::jsonb);
END;
$function$

effective_database_function_definitions.bootstrap:
CREATE OR REPLACE FUNCTION public.get_kds_bootstrap_v2()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_catalog'
AS $function$
DECLARE
  v_config jsonb;
  v_snapshot jsonb;
  v_completed jsonb;
  v_timings jsonb;
  v_store_id uuid;
  v_mode text;
BEGIN
  v_config := public.get_kds_sync_config();
  v_snapshot := public.get_emergency_station_snapshot();
  v_completed := public.get_emergency_station_today_completed();
  v_timings := public.get_emergency_station_timings();
  v_store_id := NULLIF(v_config->>'restaurant_id', '')::uuid;
  IF v_store_id IS NOT NULL THEN
    v_mode := public.get_store_fulfillment_mode(v_store_id);
  END IF;
  IF v_snapshot->'operating_workflow'->>'active_id' IS NOT NULL AND v_snapshot->>'station_type'='kitchen' THEN v_completed:='[]';v_timings:='[]'; END IF;
  RETURN jsonb_build_object(
    'sync', v_config,
    'snapshot', v_snapshot,
    'completed_orders', COALESCE(v_completed, '[]'::jsonb),
    'timings', COALESCE(v_timings, '[]'::jsonb),
    'fulfillment_mode', COALESCE(v_mode, 'paperless')
  );
END;
$function$
